function randomBytes(n:number){const b=new Uint8Array(n);crypto.getRandomValues(b);return b;}function b64url(bytes:Uint8Array){let s='';for(const b of bytes)s+=String.fromCharCode(b);return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}function fromB64url(value:string){const s=value.replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(value.length/4)*4,'=');const bin=atob(s);return Uint8Array.from(bin,c=>c.charCodeAt(0));}function token(){return b64url(randomBytes(32));}function roomCode(){const b=randomBytes(8);let out='';for(let i=0;i<8;i++)out+=ROOM_ALPHABET[b[i]%ROOM_ALPHABET.length];return out;}function normalizeRoomId(value:unknown){const out=String(value??'').normalize('NFKC').trim().replace(/\s+/g,'-').toUpperCase();return /^[A-Z0-9][A-Z0-9_-]{0,31}$/.test(out)?out:'';}async function sha256(value:string){const digest=await crypto.subtle.digest('SHA-256',encoder.encode(value));return b64url(new Uint8Array(digest));}async function passwordDigest(password:string,salt:string){const key=await crypto.subtle.importKey('raw',encoder.encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:fromB64url(salt),iterations:120000},key,256);return b64url(new Uint8Array(bits));}
