async function enforceRequestLimit(req:Request,scope:string,limit:number,windowSeconds:number){const address=requestAddress(req);if(!address)return;const key=await sha256('gomoku-rate-v1:'+secretKey()+':'+scope+':'+address),allowed=await rest('rpc/gomoku_take_rate_limit',{method:'POST',body:{p_key:key,p_limit:limit,p_window_seconds:windowSeconds}});if(allowed!==true)throw Object.assign(new Error('Too many online-room requests. Try again shortly.'),{status:429});}
