function enforceActionRate(state:any,seat:number,action:string){const bucket=actionBucket(action);if(!bucket)return;const now=Date.now(),guard=state.actionGuard&&typeof state.actionGuard==='object'?state.actionGuard:{},mine=guard[seat]&&typeof guard[seat]==='object'?{...guard[seat]}:{},last=Number(mine[bucket])||0,minMs=bucket==='chat'?250:bucket==='rename'?1500:400;if(last&&now-last<minMs)throw Object.assign(new Error('Too many room actions. Try again in a moment.'),{status:429});if(action==='chat'){const recent=(Array.isArray(state.chat)?state.chat:[]).filter((m:any)=>Number(m?.seat)===seat&&Number.isFinite(Date.parse(String(m?.at||'')))&&Date.parse(String(m.at))>now-20000);if(recent.length>=8)throw Object.assign(new Error('Chat rate limit reached. Try again in a few seconds.'),{status:429});}mine[bucket]=now;state.actionGuard={...guard,[seat]:mine};}
