const GITHUB_OIDC_ISSUER='https://token.actions.githubusercontent.com';
const GITHUB_OIDC_JWKS='https://token.actions.githubusercontent.com/.well-known/jwks';
const GITHUB_OIDC_AUDIENCE='gomoku-production-control';
const GITHUB_TRUSTED_REPOSITORY='thiepn/gomoku';
const GITHUB_TRUSTED_REPOSITORY_ID='1364049991';
const GITHUB_TRUSTED_OWNER_ID='229373572';
const GITHUB_TRUSTED_WORKFLOW_P16='thiepn/gomoku/.github/workflows/p16-release-control.yml@refs/heads/main';
