  if(String(claims.repository||'')!==GITHUB_TRUSTED_REPOSITORY||String(claims.repository_id||'')!==GITHUB_TRUSTED_REPOSITORY_ID||String(claims.repository_owner_id||'')!==GITHUB_TRUSTED_OWNER_ID)throw Object.assign(new Error('GitHub automation repository is not trusted.'),{status:403});
  if(String(claims.workflow_ref||'')!==trustedWorkflow||String(claims.ref||'')!=='refs/heads/main')throw Object.assign(new Error('GitHub automation workflow is not trusted.'),{status:403});
