    p_git_sha:gitSha,p_checks:checks,p_workflow_run_id:identity.runId,p_workflow_attempt:attempt,
    p_workflow_sha:identity.workflowSha||null,p_workflow_ref:GITHUB_TRUSTED_WORKFLOW_P16
